			t.Fatalf("%s: snapshot list: %v (%d)", tc.name, err, len(snapsList))
		}
		prefix.SnapshotPresent = true
		prefix.SnapshotIndex = snapsList[0].Index
		lastAppliedAtStart = snapsList[0].Index
	}
