// Copyright (c) 2026. Assurance harness artifact (draft, not part of the target source).
// SPDX-License-Identifier: MPL-2.0

package raft

import (
	"encoding/json"
	"fmt"
	"runtime"
	"strings"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

type caTransferTrial struct {
	Event                    string   `json:"event"`
	Trial                    int      `json:"trial"`
	Mode                     string   `json:"mode"`
	LeaderID                 string   `json:"leader_id"`
	TargetID                 string   `json:"target_id"`
	TransferError            string   `json:"transfer_error"`
	FlagAfter                bool     `json:"transfer_in_progress_after"`
	NewLeaderFound           bool     `json:"new_leader_found"`
	ReElected                bool     `json:"re_elected"`
	ApplyError               string   `json:"apply_error"`
	GetConfigurationError    string   `json:"get_configuration_error"`
	StrandedTransferFrames   []string `json:"stranded_transfer_frames"`
	OldLeaderStateAtEnd      string   `json:"old_leader_state_at_end"`
	ReturnTransferError      string   `json:"return_transfer_error"`
	LeaderLastIndex          uint64   `json:"leader_last_index_at_transfer"`
	TargetLastIndex          uint64   `json:"target_last_index_at_transfer"`
	AppliedWhilePartitioned  int      `json:"applied_while_target_partitioned"`
}

func caEmit(t *testing.T, payload interface{}) {
	t.Helper()
	blob, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(blob))
}

// TestAssurance_LeadershipTransferInterrupted observes what an interrupted
// leadership transfer leaves behind on the node that started it.
//
// Each trial runs a real three-voter cluster with the in-memory transport,
// starts a leadership transfer from the leader to a follower, and (in the
// interrupted mode) partitions the leader away from the rest so that it can no
// longer reach the target and stops being able to contact a quorum. The
// partition is then healed, the old leader is made leader again through a
// normal transfer from the current leader, and its client entry points are
// exercised. The control mode runs the same transfer without any interruption.
func TestAssurance_LeadershipTransferInterrupted(t *testing.T) {
	conf := inmemConfig(t)
	conf.Logger = hclog.NewNullLogger()

	const interrupted = 10
	const controls = 2
	trial := 0
	for i := 0; i < interrupted+controls; i++ {
		caRunTransferTrial(t, conf, trial, i >= interrupted)
		trial++
	}
}

func caRunTransferTrial(t *testing.T, conf *Config, idx int, control bool) {
	t.Helper()

	ev := caTransferTrial{
		Event: "transfer_trial",
		Trial: idx,
		Mode:  "interrupted",
	}
	if control {
		ev.Mode = "control_completed"
	}

	c := MakeCluster(3, t, conf)
	defer c.Close()

	leader := c.Leader()
	followers := c.Followers()
	target := followers[0]
	ev.LeaderID = string(leader.localID)
	ev.TargetID = string(target.localID)

	if control {
		future := leader.LeadershipTransferToServer(target.localID, target.localAddr)
		if err := future.Error(); err != nil {
			ev.TransferError = err.Error()
		}
		time.Sleep(200 * time.Millisecond)
		ev.FlagAfter = leader.getLeadershipTransferInProgress()
		ev.OldLeaderStateAtEnd = leader.getState().String()
		caEmit(t, ev)
		return
	}

	// Isolate the target first so the leader accumulates committed entries that
	// the target never receives. A transfer then has real replication work, so
	// its drain loop runs instead of completing immediately.
	c.Partition([]ServerAddress{target.localAddr})
	const backlog = 200
	var last Future
	for i := 0; i < backlog; i++ {
		last = leader.Apply([]byte(fmt.Sprintf("backlog%d", i)), 0)
	}
	if err := last.Error(); err != nil {
		t.Fatalf("trial %d: backlog apply: %v", idx, err)
	}
	ev.AppliedWhilePartitioned = backlog
	ev.LeaderLastIndex = leader.getLastIndex()
	ev.TargetLastIndex = target.getLastIndex()

	future := leader.LeadershipTransferToServer(target.localID, target.localAddr)

	// Let the transfer enter its replication drain, then cut the old leader off
	// from the rest so it can no longer reach the target and stops being able
	// to contact a quorum.
	time.Sleep(30 * time.Millisecond)
	c.Partition([]ServerAddress{leader.localAddr})
	time.Sleep(300 * time.Millisecond)
	if err := future.Error(); err != nil {
		ev.TransferError = err.Error()
	}

	c.FullyConnect()

	// Wait for the rest of the cluster to settle on a leader that is not the
	// node whose transfer was interrupted.
	deadline := time.Now().Add(3 * time.Second)
	var newLeader *Raft
	for time.Now().Before(deadline) {
		leaders := c.GetInState(Leader)
		if len(leaders) == 1 && leaders[0] != leader {
			newLeader = leaders[0]
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
	ev.NewLeaderFound = newLeader != nil
	ev.FlagAfter = leader.getLeadershipTransferInProgress()
	ev.StrandedTransferFrames = caStrandedTransferFrames()

	// Make the interrupted node leader again through a normal transfer and use
	// its client entry points.
	if newLeader != nil {
		if err := newLeader.LeadershipTransferToServer(leader.localID, leader.localAddr).Error(); err != nil {
			ev.ReturnTransferError = err.Error()
		}
		if caWaitForLeader(t, leader, 2*time.Second) {
			ev.ReElected = true
			ev.ApplyError = caErrString(leader.Apply([]byte("after-interrupt"), 0).Error())
			ev.GetConfigurationError = caErrString(leader.GetConfiguration().Error())
		}
	}
	ev.OldLeaderStateAtEnd = leader.getState().String()
	caEmit(t, ev)
}

func caWaitForLeader(t *testing.T, r *Raft, d time.Duration) bool {
	t.Helper()
	deadline := time.Now().Add(d)
	for time.Now().Before(deadline) {
		if r.getState() == Leader {
			return true
		}
		time.Sleep(10 * time.Millisecond)
	}
	return false
}

func caErrString(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

// caStrandedTransferFrames samples the goroutine dump and returns the stack of
// a goroutine left inside the leadership transfer path, so the stranded send is
// inspectable rather than inferred.
func caStrandedTransferFrames() []string {
	buf := make([]byte, 1<<20)
	n := runtime.Stack(buf, true)
	lines := strings.Split(string(buf[:n]), "\n")

	var frames []string
	for i := 0; i < len(lines); i++ {
		if !strings.HasPrefix(lines[i], "goroutine ") {
			continue
		}
		var block []string
		for j := i; j < len(lines) && strings.TrimSpace(lines[j]) != ""; j++ {
			block = append(block, strings.TrimSpace(lines[j]))
		}
		joined := strings.Join(block, "\n")
		if strings.Contains(joined, "leadershipTransfer") && strings.Contains(joined, "triggerDeferErrorCh") {
			for _, f := range block {
				if strings.HasPrefix(f, "goroutine ") || strings.Contains(f, ".go:") {
					frames = append(frames, f)
					if len(frames) >= 8 {
						break
					}
				}
			}
			if len(frames) > 0 {
				break
			}
		}
	}
	return frames
}

// Copyright (c) 2026. Assurance harness artifact (draft, not part of the target source).
// SPDX-License-Identifier: MPL-2.0

package raft

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

func caEmit(t *testing.T, payload interface{}) {
	t.Helper()
	blob, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(blob))
}

func caErrString(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

// caReachable counts the peers of a leader whose last replication contact is
// within the leader lease, split by suffrage. This is a contact reading, not a
// reachability probe: right after a partition it still reflects contacts made
// before the partition, so it is reported as an informational operand and the
// partition side is reported separately as the applicability condition.
func caReachable(leader *Raft) (voters int, nonvoters int) {
	lease := leader.config().LeaderLeaseTimeout
	now := time.Now()
	for _, server := range leader.configurations.latest.Servers {
		if server.ID == leader.localID {
			continue
		}
		repl, ok := leader.leaderState.replState[server.ID]
		if !ok {
			continue
		}
		if now.Sub(repl.LastContact()) > lease {
			continue
		}
		if server.Suffrage == Voter {
			voters++
		} else {
			nonvoters++
		}
	}
	return voters, nonvoters
}

// caVerify runs one verification through the exported client API and reports
// the outcome, the vote tally the future observed, and the quorum it was
// measured against. The tally and quorum are read through the same in-package
// accessors the target's own tests use.
func caVerify(leader *Raft, wait time.Duration) (verified bool, errText string, votes, quorum int, returned bool) {
	done := make(chan struct{})
	vf := &verifyFuture{}
	vf.init()
	go func() {
		defer close(done)
		leader.verifyCh <- vf
	}()
	<-done
	quorum = leader.quorumSize()
	waitCh := make(chan error, 1)
	go func() { waitCh <- vf.Error() }()
	select {
	case err := <-waitCh:
		return err == nil, caErrString(err), vf.votes, quorum, true
	case <-time.After(wait):
		return false, "verification did not resolve", vf.votes, quorum, false
	}
}

// TestAssurance_VerifyLeaderNonvoterAck asks whether a leader that can no
// longer reach any other voter can still be confirmed as leader because a
// nonvoter's acknowledgement is counted towards the voter quorum.
//
// The cluster is four voters with one of them demoted to nonvoter through the
// normal DemoteVoter contract, giving three voters and one nonvoter. The
// interrupted case partitions the leader together with the nonvoter, so the
// leader can reach the nonvoter but no other voter; the control case
// partitions the leader on its own, so it can reach no peer at all. In the
// interrupted case the two remaining voters are then allowed to elect their own
// leader and commit an entry, and the interrupted leader's applied index is
// compared with that commit.
func TestAssurance_VerifyLeaderNonvoterAck(t *testing.T) {
	conf := inmemConfig(t)
	conf.Logger = hclog.NewNullLogger()

	caRunVerifyTrial(t, conf, 0, true)
	caRunVerifyTrial(t, conf, 1, false)
}

func caRunVerifyTrial(t *testing.T, conf *Config, trial int, withNonvoter bool) {
	t.Helper()

	c := MakeCluster(4, t, conf)
	defer c.Close()

	leader := c.Leader()
	followers := c.Followers()
	nonvoter := followers[0]

	// Demote one voter so the configuration has three voters and one nonvoter.
	if err := leader.DemoteVoter(nonvoter.localID, 0, 0).Error(); err != nil {
		t.Fatalf("trial %d: demote: %v", trial, err)
	}
	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		if !hasVote(leader.GetConfiguration().Configuration(), nonvoter.localID) {
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	cfg := leader.configurations.latest
	if hasVote(cfg, nonvoter.localID) {
		t.Fatalf("trial %d: nonvoter still has a vote", trial)
	}

	// Baseline: the leader verifies while it can reach everyone.
	baseVerified, baseErr, baseVotes, baseQuorum, baseReturned := caVerify(leader, 2*time.Second)
	baseVoters, baseNonvoters := caReachable(leader)
	caEmit(t, map[string]interface{}{
		"event":                           "verify_baseline",
		"trial":                           trial,
		"case":                            caCaseName(withNonvoter),
		"verified":                        baseVerified,
		"error":                           baseErr,
		"votes":                           baseVotes,
		"quorum_size":                     baseQuorum,
		"returned":                        baseReturned,
		"peers_in_contact_within_lease":   baseVoters + baseNonvoters,
		"voter_peers_in_contact":          baseVoters,
		"nonvoter_reachable_only":         withNonvoter,
		"partition_leader_side_suffrages": caLeaderSideSuffrages(withNonvoter),
		"leader_last_index":               leader.getLastIndex(),
	})

	// Record a known point in the interrupted leader's own FSM.
	if err := leader.Apply([]byte("pre-partition"), 0).Error(); err != nil {
		t.Fatalf("trial %d: pre-partition apply: %v", trial, err)
	}
	beforeIndex := leader.getLastIndex()

	if withNonvoter {
		c.Partition([]ServerAddress{leader.localAddr, nonvoter.localAddr})
	} else {
		c.Partition([]ServerAddress{leader.localAddr})
	}
	time.Sleep(5 * time.Millisecond)

	reachVoters, reachNonvoters := caReachable(leader)
	verified, errText, votes, quorum, returned := caVerify(leader, 2*time.Second)
	leaderState := leader.getState().String()
	caEmit(t, map[string]interface{}{
		"event":                           "verify_partitioned",
		"trial":                           trial,
		"case":                            caCaseName(withNonvoter),
		"verified":                        verified,
		"error":                           errText,
		"votes":                           votes,
		"quorum_size":                     quorum,
		"returned":                        returned,
		"peers_in_contact_within_lease":   reachVoters + reachNonvoters,
		"voter_peers_in_contact":          reachVoters,
		"nonvoter_reachable_only":         withNonvoter,
		"partition_leader_side_suffrages": caLeaderSideSuffrages(withNonvoter),
		"leader_state":                    leaderState,
		"leader_last_index":               leader.getLastIndex(),
	})

	if !withNonvoter {
		return
	}

	// What the voters the interrupted leader cannot reach do next.
	var peerLeader *Raft
	deadline = time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		for _, r := range c.rafts {
			if r == leader || r == nonvoter {
				continue
			}
			if r.getState() == Leader {
				peerLeader = r
			}
		}
		if peerLeader != nil {
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	writeIndex := uint64(0)
	writeCommitted := false
	if peerLeader != nil {
		future := peerLeader.Apply([]byte("committed-after-partition"), 0)
		if err := future.Error(); err != nil {
			t.Logf("trial %d: peer apply: %v", trial, err)
		} else {
			writeIndex = future.Index()
			writeCommitted = true
		}
	}
	time.Sleep(100 * time.Millisecond)
	caEmit(t, map[string]interface{}{
		"event":                "peer_side",
		"trial":                trial,
		"case":                 caCaseName(withNonvoter),
		"new_leader_elected":   peerLeader != nil,
		"write_committed":      writeCommitted,
		"write_index":          writeIndex,
		"leader_applied_index": leader.getLastApplied(),
		"leader_last_index":    leader.getLastIndex(),
		"index_before_partition": beforeIndex,
		"leader_applied_lags_new_commit": writeCommitted && leader.getLastApplied() < writeIndex,
	})
}

func caCaseName(withNonvoter bool) string {
	if withNonvoter {
		return "leader_with_nonvoter_reachable"
	}
	return "leader_alone"
}

// caLeaderSideSuffrages reports which peer suffrages the harness left on the
// interrupted leader's side of the partition. This is the applicability
// condition of the two verification comparisons: in one case the only peer the
// leader can exchange RPCs with is a nonvoter, and in the control case it has
// no peer at all.
func caLeaderSideSuffrages(withNonvoter bool) []string {
	if withNonvoter {
		return []string{"Nonvoter"}
	}
	return []string{}
}

// Copyright (c) 2026. Assurance harness artifact (draft, not part of the target source).
// SPDX-License-Identifier: MPL-2.0

package raft

import (
	"encoding/json"
	"fmt"
	"math"
	"os"
	"runtime"
	"strings"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

// caRestartWait bounds how long the harness waits for a restarted node's
// NewRaft call to return before recording it as non-returning.
const caRestartWait = 5 * time.Second

type caReplayCase struct {
	name               string
	applied            int
	snapshotBeforeStop bool
	maxAppendEntries   int // 0 keeps the captured default
}

type caReplayResult struct {
	Case               string   `json:"case"`
	Applied            int      `json:"applied"`
	MaxAppendEntries   int      `json:"max_append_entries"`
	FSMBufferCapacity  int      `json:"fsm_mutate_ch_capacity"`
	PersistedCommitIdx uint64   `json:"persisted_commit_index"`
	LastLogIndex       uint64   `json:"last_log_index"`
	SnapshotPresent    bool     `json:"snapshot_present"`
	SnapshotIndex      uint64   `json:"snapshot_index"`
	LastAppliedAtStart uint64   `json:"last_applied_before_restart"`
	ReplayWindow       uint64   `json:"replay_window"`
	FSMBoundInWindow   uint64   `json:"fsm_bound_entries_in_window"`
	EstimatedBatches   uint64   `json:"estimated_replay_batches"`
	RestartReturned    bool     `json:"restart_returned"`
	RestartElapsedMs   int64    `json:"restart_elapsed_ms"`
	RestartError       string   `json:"restart_error"`
	RestartFrames      []string `json:"restart_stack_frames"`
}

func caEmit(t *testing.T, res caReplayResult) {
	t.Helper()
	blob, err := json.Marshal(res)
	if err != nil {
		t.Fatalf("marshal result: %v", err)
	}
	fmt.Println("CA_EVENT " + string(blob))
}

// TestAssurance_RestoreCommittedLogs_StartupReplay observes whether NewRaft
// returns when RestoreCommittedLogs replays a startup window of
// (last snapshot index, persisted commit index] committed entries.
//
// Each case runs the real single-voter Raft node (in-memory transport, real
// commit-tracking log store) to produce the persisted commit index and log
// contents, shuts it down, and then calls NewRaft again over the same stores.
// The cases differ only in how many entries are committed before the restart
// and whether a snapshot is taken before shutdown, i.e. in the size of the
// startup replay window.
func TestAssurance_RestoreCommittedLogs_StartupReplay(t *testing.T) {
	cases := []caReplayCase{
		{name: "small_window_default_batch", applied: 4000},
		{name: "mid_window_default_batch", applied: 1000},
		{name: "mid_window_small_batch", applied: 1000, maxAppendEntries: 4},
		{name: "large_window_default_batch", applied: 12000},
		{name: "large_window_after_snapshot", applied: 12000, snapshotBeforeStop: true},
	}
	for _, tc := range cases {
		res := caRunReplayCase(t, tc)
		caEmit(t, res)
	}
}

func caRunReplayCase(t *testing.T, tc caReplayCase) caReplayResult {
	t.Helper()

	res := caReplayResult{Case: tc.name, Applied: tc.applied}

	// Automatic snapshotting is disabled so that the startup replay window is
	// determined only by the explicit applies and the optional manual
	// snapshot. This is a legal configuration and models a node whose newest
	// snapshot lags its commit index (which also happens with default settings
	// when more than SnapshotThreshold entries are committed between the
	// periodic snapshot checks).
	conf := inmemConfig(t)
	conf.Logger = hclog.NewNullLogger()
	conf.RestoreCommittedLogs = true
	conf.SnapshotThreshold = math.MaxUint64
	conf.SnapshotInterval = time.Hour
	if tc.maxAppendEntries > 0 {
		conf.MaxAppendEntries = tc.maxAppendEntries
	}

	c := MakeClusterCustom(t, &MakeClusterOpts{
		Peers:              1,
		Bootstrap:          true,
		Conf:               conf,
		CommitTrackingLogs: true,
	})

	leader := c.Leader()

	var last Future
	for i := 0; i < tc.applied; i++ {
		last = leader.Apply([]byte(fmt.Sprintf("test%d", i)), 0)
	}
	if err := last.Error(); err != nil {
		t.Fatalf("apply %d: %v", tc.applied, err)
	}

	logs := leader.logs
	stable := leader.stable
	snaps := leader.snapshots
	fsm := leader.fsm
	addr := leader.trans.LocalAddr()

	store, ok := logs.(CommitTrackingLogStore)
	if !ok {
		t.Fatalf("log store %T does not implement CommitTrackingLogStore", logs)
	}
	commitIdx, err := store.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex: %v", err)
	}
	lastLogIdx, err := logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex: %v", err)
	}
	res.PersistedCommitIdx = commitIdx
	res.LastLogIndex = lastLogIdx
	res.MaxAppendEntries = leader.config().MaxAppendEntries
	res.FSMBufferCapacity = cap(leader.fsmMutateCh)

	var lastAppliedAtStart uint64
	if tc.snapshotBeforeStop {
		if err := leader.Snapshot().Error(); err != nil {
			t.Fatalf("snapshot: %v", err)
		}
		snapsList, err := snaps.List()
		if err != nil || len(snapsList) == 0 {
			t.Fatalf("snapshot list: %v (%d)", err, len(snapsList))
		}
		res.SnapshotPresent = true
		res.SnapshotIndex = snapsList[0].Index
		lastAppliedAtStart = snapsList[0].Index
	}
	res.LastAppliedAtStart = lastAppliedAtStart
	if commitIdx > lastAppliedAtStart {
		res.ReplayWindow = commitIdx - lastAppliedAtStart
	}

	// Census the entry types inside the startup replay window using the same
	// rule as Raft.prepareLog, so the batch arithmetic below rests on observed
	// log contents rather than on an assumed layout.
	fsmBound, err := caCountFSMBound(logs, lastAppliedAtStart+1, commitIdx, leader.protocolVersion)
	if err != nil {
		t.Fatalf("census replay window: %v", err)
	}
	res.FSMBoundInWindow = fsmBound
	if res.MaxAppendEntries > 0 {
		res.EstimatedBatches = (fsmBound + uint64(res.MaxAppendEntries) - 1) / uint64(res.MaxAppendEntries)
	}

	if err := leader.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown: %v", err)
	}

	// Restart the node over the same durable stores, exactly as the target's
	// own restart tests do, with a fresh transport on the same address.
	cfg := *conf
	cfg.Logger = hclog.NewNullLogger()

	doneCh := make(chan error, 1)
	go func() {
		defer func() {
			if r := recover(); r != nil {
				doneCh <- fmt.Errorf("panic: %v", r)
			}
		}()
		_, trans2 := NewInmemTransport(addr)
		_, err := NewRaft(&cfg, fsm, logs, stable, snaps, trans2)
		doneCh <- err
	}()

	start := time.Now()
	select {
	case rerr := <-doneCh:
		res.RestartReturned = true
		if rerr != nil {
			res.RestartError = rerr.Error()
		}
	case <-time.After(caRestartWait):
		res.RestartFrames = caBlockedReplayFrames()
	}
	res.RestartElapsedMs = time.Since(start).Milliseconds()

	for _, d := range c.dirs {
		_ = os.RemoveAll(d)
	}
	return res
}

// caCountFSMBound counts the entries in [1, upTo] that Raft.prepareLog turns
// into an entry delivered to the FSM (LogCommand, LogBarrier and, above
// protocol version 2, LogConfiguration). No-ops and the deprecated peer entry
// types are not delivered.
func caCountFSMBound(logs LogStore, from, upTo uint64, protocol ProtocolVersion) (uint64, error) {
	var bound uint64
	if from == 0 {
		from = 1
	}
	for idx := from; idx <= upTo; idx++ {
		var l Log
		if err := logs.GetLog(idx, &l); err != nil {
			return bound, fmt.Errorf("GetLog(%d): %w", idx, err)
		}
		switch l.Type {
		case LogCommand, LogBarrier:
			bound++
		case LogConfiguration:
			if protocol > 2 {
				bound++
			}
		}
